<script setup>
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {api,messageOf} from '../api'
const router=useRouter(),busy=ref(false),error=ref('');const form=reactive({title:'',description:'',category:'日用',tradeType:'FREE',price:null,pickupLocation:'',slots:[{startAt:'',endAt:''}]});const addSlot=()=>{if(form.slots.length<5)form.slots.push({startAt:'',endAt:''})};const removeSlot=i=>form.slots.splice(i,1);const local=v=>v?`${v}:00`:null;
async function submit(){error.value='';if(!form.title.trim()||!form.description.trim()||!form.pickupLocation.trim()){error.value='请完整填写物品与公共交接地点';return}if(form.tradeType==='FIXED_PRICE'&&(!form.price||Number(form.price)<=0)){error.value='标价必须大于0元';return}if(form.slots.some(x=>!x.startAt||!x.endAt||x.endAt<=x.startAt)){error.value='请填写有效的未来时段';return}busy.value=true;try{const payload={...form,price:form.tradeType==='FIXED_PRICE'?Number(form.price):null,slots:form.slots.map(x=>({startAt:local(x.startAt),endAt:local(x.endAt)}))};const {data}=await api.post('/items',payload);router.push(`/items/${data.id}`)}catch(e){error.value=messageOf(e);if(e.response?.status===401)router.push('/login')}finally{busy.value=false}}
</script>
<template><section class="panel"><p class="eyebrow">发布闲置</p><h1>把物品交给刚好需要的邻居</h1><form @submit.prevent="submit"><label>物品名称<input v-model="form.title" maxlength="100" placeholder="例如：九成新电热水壶"></label><label>描述<textarea v-model="form.description" maxlength="2000" rows="5" placeholder="说明成色、使用情况和缺陷"></textarea></label><div class="form-row"><label>分类<select v-model="form.category"><option>日用</option><option>家电</option><option>图书</option><option>数码</option><option>其他</option></select></label><label>交易方式<select v-model="form.tradeType"><option value="FREE">免费送</option><option value="NEGOTIABLE">随便给</option><option value="FIXED_PRICE">标价</option></select></label></div><label v-if="form.tradeType==='FIXED_PRICE'">价格（元）<input v-model.number="form.price" type="number" min="0.01" step="0.01"></label><label>公共交接地点<input v-model="form.pickupLocation" maxlength="200" placeholder="例如：小区南门保安亭旁"></label><fieldset><legend>可选交接时段（北京时间）</legend><div v-for="(slot,i) in form.slots" :key="i" class="slot-edit"><input v-model="slot.startAt" type="datetime-local"><span>至</span><input v-model="slot.endAt" type="datetime-local"><button v-if="form.slots.length>1" type="button" class="secondary" @click="removeSlot(i)">删除</button></div><button v-if="form.slots.length<5" type="button" class="secondary" @click="addSlot">添加时段</button></fieldset><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'发布中…':'确认发布'}}</button></form></section></template>